#!/usr/bin/env bash
# 0-18 화면별 최종 정리 — 감사 재료: ① 1차 10파일 전체 캡처 + 상태 라벨 ② 34파일 89상태 DOM 감사(JSON 1줄/상태)
B="$HOME/.claude/skills/gstack/browse/dist/browse"
D1="C:/Projects/Active/교대근무관리 시스템/시안/2026-08-31-1차HTML"
D2="C:/Projects/Active/교대근무관리 시스템/시안/2026-09-02-2차HTML"
OUT="시안/2026-09-06-최종정리"
JS() { "$B" js "$1" 2>/dev/null | grep -v "BEGIN\|END" | grep -v '^\s*$'; }
G() { "$B" goto "file:///$1" >/dev/null 2>&1; "$B" wait --load >/dev/null 2>&1; }
"$B" viewport 1440x900 >/dev/null 2>&1
AUDIT="(()=>{const vis=e=>e.getClientRects().length>0;const out=[];const f=decodeURIComponent(location.pathname.split('/').pop());document.querySelectorAll('.state-wrapper').forEach(w=>{const label=(w.querySelector('.status-label-bar')||{textContent:''}).textContent.trim().replace(/\s+/g,' ');const side=w.querySelector('.sidebar');const nav=side?[...side.querySelectorAll('.nav-item')].filter(vis).map(a=>a.textContent.trim().replace(/\s+/g,' ')):[];const groups=side?[...side.querySelectorAll('*')].filter(e=>e.children.length===0&&vis(e)&&/^(준비|운영|정산|관리|주 메뉴)$/.test(e.textContent.trim())).map(e=>e.textContent.trim()):[];const sb=w.querySelector('[class*=\"status-bar\"],[class*=\"statusbar\"],.app-status');const sbText=sb?sb.textContent.trim().replace(/\s+/g,' ').slice(0,120):'';const tables=[...w.querySelectorAll('table')].filter(vis);const tinfo=tables.map(t=>{const rows=[...t.querySelectorAll('tbody tr')].filter(vis);const h=rows.length?Math.round(rows[0].getBoundingClientRect().height):0;let c=t.parentElement,ox='';while(c&&c!==w){const o=getComputedStyle(c).overflowX;if(o==='auto'||o==='scroll'){ox=o;break;}c=c.parentElement;}const fs=[...t.querySelectorAll('td')].slice(0,60).map(td=>parseFloat(getComputedStyle(td).fontSize));const th=[...t.querySelectorAll('thead th')].filter(vis).length;return th+'열/'+rows.length+'행/h'+h+'/f'+(fs.length?Math.min(...fs):0)+'/ox:'+(ox||'없음');});const btns=[...w.querySelectorAll('button,a[href],[role=button]')].filter(vis);const primary=btns.filter(b=>/btn-primary/.test(b.className)).length;const danger=btns.filter(b=>/danger|destruct/.test(b.className)).length;const iconOnly=btns.filter(b=>{const t=[...b.childNodes].map(n=>n.nodeType===3?n.textContent:(n.getAttribute&&n.getAttribute('aria-hidden')==='true'?'':n.textContent)).join('').trim();return !t&&!b.getAttribute('aria-label')&&!b.getAttribute('title');}).length;const adis=w.querySelectorAll('[aria-disabled=\"true\"]').length;const ndis=[...w.querySelectorAll('button[disabled]')].filter(vis).length;const live=w.querySelectorAll('[aria-live],[role=status],[role=alert]').length;const modals=w.querySelectorAll('[role=dialog]').length;const badges=[...w.querySelectorAll('[class*=\"badge\"]')].filter(vis);const badgeNoText=badges.filter(b=>!b.textContent.trim()&&!b.getAttribute('title')&&!b.getAttribute('aria-label')).length;const inputs=[...w.querySelectorAll('input:not([type=hidden]),select,textarea')].filter(vis).length;const unl=[...w.querySelectorAll('input:not([type=hidden]),select,textarea')].filter(vis).filter(i=>!(i.id&&w.querySelector('label[for=\"'+i.id+'\"]'))&&!i.getAttribute('aria-label')&&!i.getAttribute('aria-labelledby')&&!i.closest('label')).length;const skel=w.querySelectorAll('[class*=\"skeleton\"]').length;const empty=w.querySelectorAll('[class*=\"empty\"]').length;const errc=w.querySelectorAll('[class*=\"error\"],[class*=\"alert\"],[class*=\"danger\"]').length;const proc=(w.textContent.match(/처리 중|중\.\.\./g)||[]).length;const heads=[...w.querySelectorAll('h1,h2,h3,.page-title,.screen-title')].filter(vis).map(h=>h.tagName+':'+h.textContent.trim().replace(/\s+/g,' ').slice(0,20));const main=w.querySelector('main,.main-content,.content');const mainW=main?Math.round(main.getBoundingClientRect().width):0;const sideW=side?Math.round(side.getBoundingClientRect().width):0;const aw=w.querySelector('.app-window');const awH=aw?Math.round(aw.getBoundingClientRect().height):0;const icons=w.querySelectorAll('.material-symbols-outlined').length;const smallText=[...w.querySelectorAll('td,li,p,span,label,div')].filter(e=>vis(e)&&e.children.length===0&&e.textContent.trim()&&parseFloat(getComputedStyle(e).fontSize)<12).length;const textLen=w.textContent.replace(/\s+/g,'').length;out.push(JSON.stringify({f,id:w.id,label,nav:nav.length,navItems:nav.join('|'),groups:groups.join('|'),sb:sbText,tables:tinfo,btns:btns.length,primary,danger,iconOnly,adis,ndis,live,modals,badges:badges.length,badgeNoText,inputs,unlabeled:unl,skel,empty,err:errc,proc,heads,sideW,mainW,awH,icons,smallText,textLen}));});return out.join('\n');})()"
echo "### 1차 캡처 + 라벨" | tee "$OUT/_labels-1차.log"
for f in "$D1"/*.html; do n=$(basename "$f" .html); G "$f"; "$B" screenshot "$OUT/캡처1차/$n.png" >/dev/null 2>&1; { echo "## $n.html ($(stat -c %s "$OUT/캡처1차/$n.png")B)"; JS "(()=>{return [...document.querySelectorAll('.status-label-bar')].map(l=>'  '+l.textContent.trim().replace(/\s+/g,' ')).join('\n');})()"; } | tee -a "$OUT/_labels-1차.log"; done
echo "### DOM 감사 34파일" 
: > "$OUT/_audit.jsonl"
for f in "$D1"/*.html "$D2"/*.html; do G "$f"; JS "$AUDIT" >> "$OUT/_audit.jsonl"; done
echo "상태 수: $(wc -l < "$OUT/_audit.jsonl")"
echo DONE
